const icons={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',file:'M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6 M9 16h6',bag:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M8 5l7 7-7 7',down:'M6 9l6 6 6-6',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4',spark:'M12 3l2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6z',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4z M10 21h4',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M18 6L6 18',search:'M21 21l-5-5 M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',clock:'M12 8v5l3 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',school:'M2 9l10-6 10 6-10 6z M6 12v6l6 3 6-3v-6 M22 9v8',leaf:'M5 20C1 8 9 3 21 3c0 12-5 20-16 17z M5 20L16 9',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
const I=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const brand=()=>`<div class="brand"><span class="brand-mark">${I('bag')}</span>启程<span class="pill blue" style="font-size:10px;letter-spacing:0">BETA</span></div>`;
const modes={intern:{label:'找实习',desc:'从第一次尝试，找到自己的方向。',icon:'leaf',plan:'我的实习计划',role:'后端开发实习生',season:'日常实习 · 可转正'},campus:{label:'校园招聘',desc:'把每一次准备，变成更好的机会。',icon:'school',plan:'2027 届秋招计划',role:'后端开发工程师',season:'2027 校招 · 正式批'},social:{label:'社会招聘',desc:'带上积累，走向职业的下一程。',icon:'bag',plan:'我的职业新计划',role:'高级后端工程师',season:'社会招聘 · 技术方向'}};
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x)),uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const experienceSeed=[{id:'e1',title:'青禾科技 · 后端研发实习',date:'2026.06 — 2026.09',body:'参与内部任务调度平台开发，负责任务状态查询与异常重试模块。使用 Java、Spring Boot 和 Redis 实现任务缓存与状态同步。',visible:true},{id:'e2',title:'轻舟 · 校园二手交易平台',date:'2026.02 — 2026.05',body:'与三位同学共同完成校园交易项目，独立负责商品检索与订单模块。设计订单状态流转，使用事务与幂等校验处理重复提交。',visible:true},{id:'e3',title:'开源社区 · 文档维护',date:'2025.10 — 至今',body:'参与技术文档整理与问题反馈，补充本地运行说明和常见问题，协助新贡献者理解项目结构。',visible:false}];
function newResume(name,kind='通用简历'){const r={id:uid(),name,kind,person:'林一舟',headline:'后端开发 · Java / Spring Boot / Redis',education:'江南理工大学 · 计算机科学与技术 · 本科 · 2023 — 2027',contact:'linyizhou@example.com · 杭州',experiences:clone(experienceSeed),updated:'今天',versions:[]};r.versions=[{id:uid(),label:'初始版本',time:'9 月 12 日',snapshot:clone({...r,versions:undefined})}];return r}
const seed={mode:null,resumes:[newResume('后端研发 · 通用版'),newResume('青禾科技 · 定向版','岗位定向'),newResume('数据工程 · 项目版','方向简历'),newResume('英文简历 · Backend','英文版')],applications:[],favorites:[],tasksDone:[],orders:[],reviews:[],purchases:[],discovery:false,invites:[],partners:[{id:'p1',name:'周以安',role:'技术猎头',company:'远川人才',status:'待开通',verified:true,paid:true,expires:'2026-12-31'},{id:'p2',name:'陈知远',role:'简历顾问',company:'独立顾问',status:'已开通',verified:true,paid:true,expires:'2026-12-31'},{id:'p3',name:'许清',role:'面试教练',company:'独立顾问',status:'待核验',verified:false,paid:false,expires:'2026-12-31'}]};
const companies=[{id:'j1',name:'青禾科技',initial:'青',color:'#4069df',city:'杭州',team:'企业服务 · B 轮 · 200–500 人',skills:'Java / 分布式 / Redis',desc:'参与企业协同产品的后端研发，负责业务模块设计、接口开发与系统稳定性改进。',ref:'QH2027',salary:'18–25K · 14薪'},{id:'j2',name:'星野网络',initial:'星',color:'#8c65b2',city:'上海',team:'互联网 · C 轮 · 500–1000 人',skills:'Java / MySQL / 微服务',desc:'围绕内容社区的核心业务，参与高并发服务设计、性能优化与跨团队技术协作。',ref:'XYTECH',salary:'20–30K · 15薪'},{id:'j3',name:'泊舟数据',initial:'泊',color:'#268c7b',city:'北京',team:'数据服务 · A 轮 · 100–200 人',skills:'Python / SQL / 数据工程',desc:'开发数据处理与质量监测工具，参与数据流水线设计，帮助业务团队获得准确可靠的数据。',ref:'BOZHOU',salary:'20–28K · 14薪'},{id:'j4',name:'云帆智能',initial:'云',color:'#ce8754',city:'深圳',team:'人工智能 · B 轮 · 200–500 人',skills:'Python / LLM / RAG',desc:'参与智能应用研发与评估，建设可追踪的模型调用、检索和反馈流程。',ref:'YFTECH',salary:'22–32K · 14薪'}];
for(const m of Object.keys(modes)){seed.applications.push(...companies.slice(0,3).map((c,i)=>({id:uid(),company:c.name,role:m==='intern'?modes[m].role:modes[m].role,mode:m,stage:['面试','已投递','准备中'][i],date:'2026-09-'+(12+i),resumeId:seed.resumes[i?0:1].id,snapshot:clone(seed.resumes[i?0:1]),history:['9 月 12 日 · 材料已归档'],note:''})))}
let state;try{state=JSON.parse(localStorage.getItem('qicheng-prototype-v1'))||clone(seed)}catch{state=clone(seed)}
let mode=state.mode,page='today',role='user',selectedResume=state.resumes[0].id,editorTab='edit',query='',filter='全部',appView='board',serviceView='browse',practiceStep=0,practiceAnswers=[];
const titleMap={today:'今天',resumes:'我的简历',jobs:'岗位与公司',applications:'投递与日历',practice:'面试与成长',market:'简历市场',services:'人工服务',hunters:'找猎头',admin:'合作方管理',provider:'服务协作',reviews:'复盘库',community:'面经社区',opportunities:'我的机会',recruiter:'企业招聘台',hunterdesk:'猎头工作台',chat:'AI 模拟面试'};
function persist(){state.mode=mode;try{localStorage.setItem('qicheng-prototype-v1',JSON.stringify(state))}catch{toast('浏览器存储不可用，本次更改仅保留到关闭页面。')}}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('visible'),3200)}
function go(p){if(p==='hunters'&&mode!=='social')p='today';page=p;query='';filter='全部';history.replaceState(null,'','#'+p);render();window.scrollTo(0,0)}
function chooseMode(m){if(!modes[m])throw Error('不支持的求职模式');mode=m;role='user';page='today';persist();render()}
const act=(a,text,cls='btn',data='')=>`<button type="button" class="${cls}" data-act="${a}" ${data}>${text}</button>`;
const pill=(t,c='')=>`<span class="pill ${c}">${E(t)}</span>`;
const logo=c=>`<span class="company-logo" style="--logo:${c.color}">${c.initial}</span>`;
const field=(label,name,value='',type='text')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${E(value)}" required></label>`;
function modal(title,body,footer=''){const d=document.getElementById('dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${act('close',I('close'),'icon-button','aria-label="关闭"')}</div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-foot">${footer}</div>`:''}`;if(!d.open)d.showModal()}
function formModal(title,body,label,submit){modal(title,`<form id="modal-form">${body}<p id="form-error" class="error" role="alert"></p><div class="form-actions">${act('close','取消','btn ghost')}<button class="btn primary" type="submit">${label}</button></div></form>`);document.getElementById('modal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);submit(f)}}
function close(){document.getElementById('dialog').close()}
function head(title,desc,buttons=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="row">${buttons}</div></div>`}
function navItems(){return role==='admin'?[['admin','settings','合作方管理'],['services','calendar','服务与回访']]:role==='provider'?[['provider','calendar','我的服务单']]:[['today','home','今天'],['resumes','file','我的简历'],['jobs','bag','岗位与公司'],['applications','grid','投递与日历'],['practice','spark','面试与成长'],['market','grid','简历市场'],['services','people','人工服务'],...(mode==='social'?[['hunters','people','找猎头']]:[])]}
function render(){if(!mode){document.getElementById('app').innerHTML=`<main class="intro"><div class="intro-head">${brand()}<span class="pill">交互原型 · 演示数据</span></div><section class="intro-main"><div class="eyebrow">YOUR NEXT CHAPTER</div><h1>下一程，从这里开始。</h1><p class="lead">选择你正在寻找的机会，我们一起把求职这件事理清楚。</p><div class="mode-grid">${Object.entries(modes).map(([k,v])=>`<button class="mode-card" data-mode="${k}"><div class="mode-icon">${I(v.icon)}</div><h2>${v.label}</h2><p>${v.desc}</p><div class="enter">进入工作台 ${I('arrow')}</div></button>`).join('')}</div><div class="intro-foot"><span>简历 · 机会 · 面试 · 每一个下一步</span><span>之后可以随时切换，已有材料会保留。</span></div></section></main>`;return}
if(page==='hunters'&&mode!=='social')page='today';const nav=navItems();const names={user:'个人工作台',admin:'平台管理 · 演示',provider:'服务协作 · 演示',recruiter:'企业招聘 · 演示',hunter:'猎头工作台 · 演示'};document.title=`${titleMap[page]} · 启程`;
document.getElementById('app').innerHTML=`<aside class="sidebar">${brand()}${act('switch',`${modes[mode].label}${I('down')}`,'workspace-switch')}<div class="nav-label">${names[role]}</div><nav class="nav" aria-label="主导航">${nav.map(([id,ic,t])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${I(ic)}${t}${id==='applications'?'<span class="count">'+state.applications.filter(a=>a.mode===mode).length+'</span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">${I('spark')} 让每一份准备，<br>　 都成为下一步的底气。</div>${act('role',`${I('settings')} 切换体验视角`,'btn ghost full')}<div class="profile"><div class="avatar">${role==='user'?'林':role==='admin'?'管':'陈'}</div><div><strong>${role==='user'?'林一舟':role==='admin'?'平台负责人':role==='hunter'?'周以安':role==='recruiter'?'青禾科技 HR':'陈知远'}</strong><span>${names[role]}</span></div></div></div></aside><div class="main"><header class="topbar"><div class="crumb">${names[role]} <span style="margin:0 12px">/</span> <b>${titleMap[page]}</b></div><div class="mobile-nav">${act('mobile-menu',I('grid'),'icon-button','aria-label="展开导航"')}<strong>${titleMap[page]}</strong></div><div class="top-actions"><span class="pill">交互原型</span><span class="label">9 月 16 日，星期三</span>${act('notifications',I('bell'),'icon-button','aria-label="通知中心"')}</div></header><main class="content" id="main-content">${({today:today,resumes:resumes,jobs:jobs,applications:applications,practice:practice,market:market,services:services,hunters:hunters,admin:admin,provider:provider,reviews:reviewLibrary,community:community,opportunities:opportunities,recruiter:recruiterDesk,hunterdesk:hunterDesk,chat:chatView})[page]()}</main><footer class="app-footer">所有人物、公司与交易均为演示数据 · 更改仅保存在当前浏览器 ${act('reset','重置演示','text-btn')}</footer></div>`}
function today(){const apps=state.applications.filter(a=>a.mode===mode),tasks=[{id:'t1',icon:'calendar',title:'准备青禾科技的技术一面',desc:'从你投出的简历出发，梳理项目细节与常见追问。',time:'明天 14:00',dur:'预计 25 分钟',action:'prepare',cta:'开始准备'},{id:'t2',icon:'file',title:'再打磨一下后端研发简历',desc:'检查项目表述，保留最能体现你能力的经历。',time:'今天',dur:'预计 15 分钟',action:'edit-first',cta:'修改简历'},{id:'t3',icon:'bell',title:'确认星野网络的笔试安排',desc:'一条新的通知已整理好，等待你确认时间。',time:'待确认',dur:'预计 2 分钟',action:'confirm-notice',cta:'查看通知'}].filter(t=>!state.tasksDone.includes(mode+t.id));return head('下午好，一舟 <span class="greeting">✳</span>',`把注意力留给值得的机会。今天有 ${tasks.length} 件事等你推进。`,act('add-job',I('plus')+' 添加机会','btn primary'))+`<div class="card welcome"><div><div class="eyebrow">${modes[mode].plan}</div><h2>${mode==='intern'?'从一次实践，找到你的方向。':mode==='social'?'下一步，走向更适合你的团队。':'下一场面试，准备得更从容。'}</h2><p>${mode==='intern'?'可到岗时间、每周天数、期待的成长，一起考虑。':mode==='social'?'梳理你的技术积累，找到能够发挥所长的机会。':'明天 14:00 · 青禾科技 · 后端开发工程师'}</p></div>${act('prepare','准备这场面试 '+I('arrow'),'btn primary')}</div><div class="stats">${[['收藏的机会',state.favorites.length,'jobs','bag'],['进行中的投递',apps.filter(a=>!['已结束','Offer'].includes(a.stage)).length,'applications','grid'],['待参加面试',apps.filter(a=>a.stage==='面试').length,'practice','calendar'],['我的简历',state.resumes.length,'resumes','file']].map(([t,n,p,i])=>`<button class="card stat" data-page="${p}"><div class="stat-top">${t}${I(i)}</div><strong>${n.toString().padStart(2,'0')}</strong><small>${p==='resumes'?'按方向自由组织':'查看详情'} ${I('arrow')}</small></button>`).join('')}</div><div class="dashboard-grid"><div class="stack"><section class="card"><div class="section-head"><h2>今天，先做这几件事</h2>${pill(tasks.length+' 项待办','blue')}</div>${tasks.length?tasks.map(t=>`<div class="task"><span class="square-icon">${I(t.icon)}</span><div class="task-content"><div class="task-title">${t.title}</div><p class="label">${t.desc}</p><div class="meta">${pill(t.time,t.id==='t1'?'orange':'')} <span style="margin-left:8px">${t.dur}</span></div></div>${act(t.action,t.cta,'btn sm')}</div>`).join(''):'<div class="empty">'+I('check')+' 今天的事项已处理，留一点时间给自己。</div>'}</section><section class="card"><div class="section-head"><h2>值得看看</h2><button class="text-btn" data-page="jobs">全部机会 ${I('arrow')}</button></div><div class="recommend-grid">${companies.slice(2,4).map(c=>`<button class="recommend-job" data-act="job" data-id="${c.id}"><div class="row">${logo(c)}<div><h3>${c.name}</h3><span class="meta">${c.city} · ${modes[mode].season}</span></div></div><p>${c.id==='j3'?'数据开发':modes[mode].role}</p><span class="meta">${c.skills}</span></button>`).join('')}</div></section></div><div class="stack"><section class="card"><div class="section-head"><h2>本周日程</h2><span class="meta">9.14 — 9.20</span></div><div class="week">${['一','二','三','四','五','六','日'].map((d,i)=>`<div class="${i===2?'selected':''}"><span>${d}</span><b>${14+i}</b>${i===3||i===4?'<i></i>':''}</div>`).join('')}</div><button class="schedule-item" data-act="prepare"><span class="schedule-line"></span><div><strong>青禾科技 · 技术一面</strong><p>明天 14:00 — 15:00</p>${pill('视频面试','blue')}</div></button><button class="schedule-item" data-act="confirm-notice"><span class="schedule-line amber"></span><div><strong>星野网络 · 在线笔试</strong><p>周五 19:00 — 21:00</p>${pill(state.tasksDone.includes(mode+'t3')?'已确认':'待确认','orange')}</div></button></section><section class="card guide-card"><span class="square-icon">${I('people')}</span><h3>有些问题，和有经验的人聊聊。</h3><p class="label">简历修改、模拟面试与专项辅导，找到适合你的帮助。</p><button class="text-btn" data-page="services">看看人工服务 ${I('arrow')}</button></section></div></div>`}
function miniResume(r,tone=''){return `<div class="mini-resume ${tone}"><strong>${E(r.person||'林一舟')}</strong><span>${E(r.headline||'后端开发工程师')}</span><div class="mini-rule"></div><b>教育经历</b><p>${E(r.education||'计算机科学与技术 · 本科')}</p><b>项目经历</b>${(r.experiences||experienceSeed).filter(e=>e.visible).slice(0,2).map(e=>`<p><strong>${E(e.title)}</strong></p><p>${E(e.body)}</p>`).join('')}<b>专业技能</b><p>Java / Spring Boot / Redis / MySQL</p></div>`}
function resumes(){const r=state.resumes.find(x=>x.id===selectedResume)||state.resumes[0];return head('我的简历','不同的机会，用不同的方式介绍自己。',act('new-resume',I('plus')+' 新建简历','btn primary'))+`<div class="resume-layout"><aside class="resume-list">${state.resumes.map(x=>`<button data-act="select-resume" data-id="${x.id}" class="resume-item ${r.id===x.id?'active':''}"><span class="square-icon">${I('file')}</span><div><strong>${E(x.name)}</strong><span>${E(x.kind)} · ${x.versions.length} 个版本</span></div></button>`).join('')}<div class="note">经历库可以完整，简历只保留你想呈现的部分。</div></aside><section class="resume-work"><div class="editor-toolbar"><div><h3>${E(r.name)}</h3><span class="meta" id="save-status">修改自动保存在本机</span></div><div class="row">${act('duplicate','复制 / 新建','btn sm',`data-id="${r.id}"`)}${act('english','生成英文版','btn sm')}${act('delete-resume','移入回收站','btn sm')}${act('save-version','保存版本','btn sm primary')}${act('export','导出','btn sm')}</div></div><div class="tabs" role="tablist">${[['edit','编辑简历'],['preview','预览'],['versions',`版本历史 (${r.versions.length})`],['publish','分享与发布']].map(([k,t])=>`<button role="tab" aria-selected="${editorTab===k}" class="${editorTab===k?'active':''}" data-act="editor-tab" data-id="${k}">${t}</button>`).join('')}</div>${editorTab==='edit'?`<div class="editor-columns"><div class="edit-fields"><div class="section-head"><h3>基本信息</h3>${act('rename','重命名','text-btn')}</div><label class="field"><span>姓名</span><input data-edit="person" value="${E(r.person)}"></label><label class="field"><span>求职方向</span><input data-edit="headline" value="${E(r.headline)}"></label><label class="field"><span>教育经历</span><input data-edit="education" value="${E(r.education)}"></label><label class="field"><span>联系方式（示例）</span><input data-edit="contact" value="${E(r.contact)}"></label><label class="field"><span>专业技能</span><input data-edit="skills" value="${E(r.skills||'Java · Spring Boot · Redis · MySQL · Git')}"></label><div class="section-head"><h3>选择要展示的经历</h3>${act('add-experience',I('plus'),'icon-button','aria-label="新增经历"')}</div>${r.experiences.map(e=>`<div class="experience-field ${!e.visible?'hidden-exp':''}"><label class="check"><input type="checkbox" data-exp-visible="${e.id}" ${e.visible?'checked':''}><strong>${E(e.title)}</strong></label><div class="meta">${E(e.date)} · ${e.visible?'显示在此简历':'已隐藏，AI 不会自动加入'}</div>${e.visible?`<label class="field"><span>经历名称</span><input data-exp-id="${e.id}" data-exp-field="title" value="${E(e.title)}"></label><label class="field"><span>时间范围</span><input data-exp-id="${e.id}" data-exp-field="date" value="${E(e.date)}"></label><label class="field"><span class="sr-only">${E(e.title)}的描述</span><textarea data-exp-text="${e.id}">${E(e.body)}</textarea></label>${act('ai-edit',I('spark')+' 优化表达','text-btn',`data-id="${e.id}"`)}`:''}</div>`).join('')}</div><div class="preview-pane"><div class="row between"><span class="meta">简历预览</span>${pill('A4 · 中文简洁')}</div><div id="resume-preview">${resumePaper(r)}</div></div></div>`:editorTab==='preview'?`<div class="standalone-preview">${resumePaper(r)}</div>`:editorTab==='versions'?`<div class="versions"><div class="note">每份简历独立管理版本。恢复会新增一个版本，不会改动已经投出的材料。</div>${[...r.versions].reverse().map((v,i)=>`<div class="version-item"><div class="version-point ${i===0?'latest':''}"></div><div class="grow"><h3>${E(v.label)} ${i===0?pill('最新快照','blue'):''}</h3><p class="meta">${E(v.time)} · ${v.snapshot.experiences.filter(e=>e.visible).length} 段可见经历</p></div>${act('compare-version','查看与比较','btn sm',`data-id="${v.id}"`)}${act('restore-version','恢复此版本','btn sm',`data-id="${v.id}"`)}</div>`).join('')}</div>`:`<div class="publish-grid"><div class="card"><span class="square-icon">${I('grid')}</span><h3>发布到简历市场</h3><p class="label">分享排版、表达和取舍方法。发布副本与你的私有简历分开。</p>${act('publish-resume','创建发布副本','btn primary')}</div><div class="card"><span class="square-icon">${I('people')}</span><h3>对招聘方展示</h3><p class="label">${mode==='social'?'由你选择是否让已核验猎头发现这份社招简历。':'你的简历目前仅自己可见。实习和校招不进入猎头人才池。'}</p>${act('visibility','管理这份简历的可见范围','btn')}</div></div>`}</section></div>`}
function resumePaper(r){return `<article class="resume-paper"><h2>${E(r.person)}</h2><p class="paper-headline">${E(r.headline)}</p><p class="paper-contact">${E(r.contact)}</p><h4>教育经历</h4><p>${E(r.education)}</p>${r.experiences.filter(e=>e.visible).map(e=>`<h4>${E(e.title)}</h4><p class="paper-date">${E(e.date)}</p><p>${E(e.body)}</p>`).join('')}<h4>专业技能</h4><p>${E(r.skills||'Java · Spring Boot · Redis · MySQL · Git')}</p>${r.reference?'<p class="reference-warning">参考样例：请替换为你自己的经历后再用于求职。</p>':''}</article>`}
function toolbar(placeholder,filters){return `<div class="toolbar"><label class="searchbox">${I('search')}<input id="search-input" placeholder="${placeholder}" value="${E(query)}"></label><div class="filters">${filters.map(f=>act('filter',f,filter===f?'chip active':'chip',`data-id="${f}"`)).join('')}</div></div>`}
function jobs(){let cs=companies.filter(c=>(c.name+c.city+c.skills).toLowerCase().includes(query.toLowerCase())&&(filter!=='已收藏'||state.favorites.includes(c.id)));return head('岗位与公司','找到值得投入的机会，也找到通往它的入口。',act('add-job',I('plus')+' 添加机会','btn primary'))+toolbar('搜索公司、城市或技术方向',['全部','已收藏'])+`<div class="row between list-caption"><span class="label">${modes[mode].season} · ${cs.length} 个演示岗位</span>${pill('更新于今天','green')}</div><div class="job-grid">${cs.map(c=>`<article class="card job-card"><div class="row between"><div class="row">${logo(c)}<div><h3>${c.name}</h3><span class="meta">${c.team}</span></div></div>${act('favorite',state.favorites.includes(c.id)?'已收藏':'收藏','btn sm',`data-id="${c.id}"`)}</div><h2>${c.id==='j3'?(mode==='intern'?'数据开发实习生':'数据开发工程师'):modes[mode].role}</h2><div class="salary">${mode==='intern'?'200–300 元/天':mode==='social'?'25–40K · 14薪':c.salary}</div><p class="label">${c.city} · ${mode==='intern'?'每周 4 天 · 3 个月起':mode==='social'?'3–5 年经验 · 本科':'2027 届 · 本科及以上'}</p><div class="skill-row">${c.skills.split(' / ').map(s=>pill(s)).join('')}</div><div class="job-card-footer">${pill('有内推入口','green')}${act('job','查看岗位 '+I('arrow'),'text-btn',`data-id="${c.id}"`)}</div></article>`).join('')||'<div class="empty">没有找到匹配的岗位，试试其他关键词。</div>'}</div>`}
function applications(){const arr=state.applications.filter(a=>a.mode===mode);return head('投递与日历','每一份材料、每一个进展，都有迹可循。',act('add-application',I('plus')+' 记录投递','btn primary'))+`<div class="row between list-caption"><div class="tabs compact">${['board','table','calendar'].map((v,i)=>act('app-view',['看板','表格','日历'][i],appView===v?'active':'',`data-id="${v}"`)).join('')}</div><span class="label">${modes[mode].plan} · ${arr.length} 条申请</span></div>${appView==='board'?`<div class="kanban">${['准备中','已投递','面试','Offer','已结束'].map((stage,i)=>`<section class="kanban-column"><div class="kanban-title"><span class="stage-dot s${i}"></span>${stage}<span>${arr.filter(a=>a.stage===stage).length}</span></div>${arr.filter(a=>a.stage===stage).map(a=>`<button class="application-card" data-act="application" data-id="${a.id}"><span class="meta">${E(a.company)}</span><h3>${E(a.role)}</h3><div class="meta">${I('file')} ${E(a.snapshot?.name||'未关联简历')}</div><div class="row between"><span class="meta">${E(a.date)}</span>${I('chevron')}</div></button>`).join('')||'<div class="column-empty">新的进展，从这里开始</div>'}</section>`).join('')}</div>`:appView==='table'?`<div class="card table-wrap"><table><thead><tr><th>公司 / 岗位</th><th>阶段</th><th>投递材料</th><th>时间</th><th></th></tr></thead><tbody>${arr.map(a=>`<tr><td><strong>${E(a.company)}</strong><br><span class="meta">${E(a.role)}</span></td><td>${pill(a.stage,'blue')}</td><td>${E(a.snapshot?.name||'未关联')}</td><td>${E(a.date)}</td><td>${act('application','查看','text-btn',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="card calendar-view"><div class="section-head"><h2>2026 年 9 月</h2><span class="label">已记录的面试与笔试安排</span></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>`<strong>${x}</strong>`).join('')}${Array.from({length:35},(_,i)=>{const n=i;return `<div class="calendar-day ${n===16?'now':''}"><span>${n>0&&n<=30?n:''}</span>${n===17?act('prepare','14:00 青禾 · 一面','calendar-event'):n===18?act('confirm-notice','19:00 星野 · 笔试','calendar-event orange'):''}</div>`}).join('')}</div></div>`}`}
const products=[{id:'m1',title:'后端校招：把项目写清楚',author:'陈知远',price:29,tags:'校招 / 后端 / 逐段讲解',tone:'blue',desc:'一份完整简历 + 项目表达拆解 + 可编辑版式。'},{id:'m2',title:'第一份实习简历，也能有重点',author:'周予',price:19,tags:'实习 / 通用 / 入门',tone:'green',desc:'没有正式工作经历，也能讲清楚你做过什么。'},{id:'m3',title:'资深工程师的技术与业务表达',author:'许清',price:49,tags:'社招 / 研发 / 结构方法',tone:'purple',desc:'围绕职责、决策与结果，组织你的技术积累。'}];
function market(){const ps=products.filter(p=>(p.title+p.tags).includes(query)&&(filter==='全部'||p.tags.includes(filter)));return head('简历市场','学习优秀的表达，把它变成属于自己的简历。',act('my-purchases','我的购买','btn'))+toolbar('搜索方向、阶段或作品',['全部','实习','校招','社招'])+`<div class="market-banner"><div><span class="eyebrow">CURATED RESUMES</span><h2>好的简历，不止是一张模板。</h2><p>看见内容背后的取舍，也找到自己的表达。</p></div>${pill('预览 · 讲解 · 可编辑','blue')}</div><div class="market-grid">${ps.map(p=>`<article class="card market-card"><button class="market-preview ${p.tone}" data-act="product" data-id="${p.id}">${miniResume({person:p.author,headline:p.title,experiences:experienceSeed})}<span class="preview-label">查看完整预览 ${I('arrow')}</span></button><div class="market-info"><div class="skill-row">${p.tags.split(' / ').map(t=>pill(t)).join('')}</div><h3>${p.title}</h3><p class="label">${p.desc}</p><div class="row between"><span class="meta">${p.author} · 创作者</span><strong class="price">¥${p.price}</strong></div>${act('product',state.purchases.includes(p.id)?'已购买 · 再次导入':'预览与导入','btn full',`data-id="${p.id}"`)}</div></article>`).join('')||'<div class="empty">暂无匹配作品</div>'}</div><div class="note" style="margin-top:24px">购买的是排版、样例与表达方法。导入后，请用自己的真实经历替换示例内容。</div>`}
const servicesData=[{id:'s1',name:'陈知远',initial:'陈',color:'#4664c0',title:'让经历更有重点',type:'简历修改',special:'后端研发 / 数据工程',bio:'专注技术简历的内容取舍与项目表达。',price:199,detail:'45 分钟沟通 + 逐段修改建议 + 2 轮修改',tags:['实习','校招','社招']},{id:'s2',name:'许清',initial:'许',color:'#298779',title:'在真正面试前，练一场',type:'模拟面试',special:'Java / 系统设计',bio:'从项目深挖到技术追问，获得具体的改进反馈。',price:299,detail:'60 分钟模拟 + 30 分钟复盘 + 书面反馈',tags:['校招','社招']},{id:'s3',name:'周予',initial:'周',color:'#986aab',title:'为你的下一场面试做准备',type:'面试辅导',special:'通用准备 / 项目表达',bio:'一起梳理面试思路，练习讲清楚自己的贡献。',price:249,detail:'2 次 45 分钟辅导 + 准备清单 + 7 天答疑',tags:['实习','校招','社招']}];
function services(){if(role==='admin')return adminOrders();const items=servicesData.filter(s=>filter==='全部'||s.type===filter);return head('人工服务','有些问题，和有经验的人认真聊一次。',act('service-view',serviceView==='orders'?'浏览服务':'我的服务单'+(state.orders.length?' · '+state.orders.length:''),'btn',`data-id="${serviceView==='orders'?'browse':'orders'}"`))+(serviceView==='orders'?ordersView():`<div class="service-intro"><div><h2>AI 帮你整理，专业的人帮你看得更深。</h2><p>由平台负责人逐个对接服务资源，交付内容与修改范围事先说清楚。</p></div>${pill('适用于实习 / 校招 / 社招','blue')}</div><div class="filters standalone">${['全部','简历修改','模拟面试','面试辅导'].map(t=>act('filter',t,filter===t?'chip active':'chip',`data-id="${t}"`)).join('')}</div><div class="service-grid">${items.map(s=>`<article class="card service-card"><div class="row between"><span class="expert-avatar" style="background:${s.color}">${s.initial}</span>${pill('身份已核验','green')}</div><h2>${s.name}</h2><p class="label">${s.special}</p><div class="service-divider"></div><span class="eyebrow">${s.type}</span><h3>${s.title}</h3><p class="label">${s.bio}</p><div class="service-detail">${I('check')} ${s.detail}</div><div class="skill-row">${s.tags.map(t=>pill(t)).join('')}</div><div class="row between"><span class="price">¥${s.price}<small> / 次</small></span>${act('book','查看与预约','btn primary',`data-id="${s.id}"`)}</div></article>`).join('')}</div><div class="reward-banner"><span class="square-icon">${I('check')}</span><div><h3>完成服务，真实回访可申请 ¥10 奖励</h3><p class="label">需核验服务单与交付记录。反馈好坏不影响资格，不要求公开好评。</p></div>${act('reward-rules','查看规则','text-btn')}</div>`)}
function ordersView(){return `<div class="stack">${state.orders.length?state.orders.map(o=>`<article class="card"><div class="row between"><div><span class="meta">服务单 ${o.id.toUpperCase()}</span><h3>${E(o.type)} · ${E(o.provider)}</h3><p class="label">${E(o.slot)} · ¥${o.price}</p></div>${pill(o.status,o.status==='已完成'?'green':'blue')}</div><p class="note" style="margin:18px 0">${E(o.detail)}<br>关联材料：${E(o.resumeName)} · 仅此订单授权</p><div class="row between"><span class="meta">${o.reward||'回访奖励：完成服务后可申请'}</span><div class="row">${o.status==='待确认'?act('order-step','模拟服务方接单','btn',`data-id="${o.id}"`):o.status==='待服务'?act('order-step','模拟完成服务','btn',`data-id="${o.id}"`):''}${o.status==='已完成'&&!o.reward?act('claim-reward','提交回访 · 申请 ¥10','btn primary',`data-id="${o.id}"`):''}${act('order-support','改期 / 售后','btn ghost',`data-id="${o.id}"`)}</div></div></article>`).join(''):`<div class="card empty">${I('calendar')}<h3>还没有预约的服务</h3><p>先了解服务内容，再选择适合你的人。</p>${act('service-view','浏览人工服务','btn primary','data-id="browse"')}</div>`}</div>`}
function hunters(){return head('找猎头','只向合适的人，开放你选择的那一面。',act('discovery',state.discovery?'人才展示：已开启':'设置人才展示','btn'))+`<div class="card privacy-banner"><span class="square-icon">${I('people')}</span><div class="grow"><h3>${state.discovery?'你的社招展示版本已开放给核验猎头':'你还没有开启猎头发现'}</h3><p class="label">私有经历和其他投递不公开。每次推荐给具体公司，仍需要你的授权。</p></div>${pill(state.discovery?'主动开放':'默认私有',state.discovery?'green':'')}</div><div class="service-grid" style="margin-top:24px">${[{name:'周以安',initial:'周',color:'#4168b0',org:'远川人才',focus:'后端研发 · 基础架构',jobs:'青禾科技 · 高级后端工程师'},{name:'沈知夏',initial:'沈',color:'#8a68a6',org:'澄明咨询',focus:'数据工程 · 算法应用',jobs:'泊舟数据 · 数据工程师'}].map((h,i)=>`<article class="card service-card"><div class="row between"><span class="expert-avatar" style="background:${h.color}">${h.initial}</span>${pill('人工核验','green')}</div><h2>${h.name}</h2><p class="label">${h.org} · ${h.focus}</p><div class="service-divider"></div><h3>当前合作岗位</h3><p class="label">${h.jobs}</p><div class="skill-row">${pill('杭州 / 上海')}${pill('3 年以上经验')}</div>${act('hunter-invite',state.invites.includes(h.name)?'已提交意向':'查看岗位并沟通','btn primary full',`data-name="${h.name}"`)}</article>`).join('')}</div><div class="note" style="margin-top:24px">猎头合作由平台负责人逐个对接与开通。本站不提供自助认证或付款升级身份。</div>`}
function practice(){return head('面试与成长','从你的经历出发，把回答练得更清楚。',act('practice-human','预约人工模拟','btn'))+`<div class="practice-layout"><section class="card"><div class="row between"><div><span class="eyebrow">青禾科技 · 技术一面</span><h2 style="margin-top:8px">你的定向面试准备包</h2></div>${pill('明天 14:00','orange')}</div><div class="note" style="margin:22px 0">${I('file')} 依据：青禾科技 · 定向版（投递快照）<br>关注点：项目职责、订单状态流转、重复请求处理</div><div class="practice-question"><span class="label">问题 ${Math.min(practiceStep+1,3)} / 3</span><h2>${['请介绍校园交易项目中，你独立负责的部分。','你是如何处理订单重复提交的？还有哪些边界情况？','如果要让这个项目服务更多用户，你会先改进什么？'][Math.min(practiceStep,2)]}</h2><p class="label">先讲背景和你的职责，再用一个具体决策说明思路。</p><label class="field"><span class="sr-only">练习回答</span><textarea id="practice-answer" placeholder="试着用 2–3 分钟的表达，写下你的回答…">${E(practiceAnswers[practiceStep]||'')}</textarea></label><div class="row between">${pill('文字练习 · 示例反馈')}${act('practice-next',practiceStep>=2?'完成练习':'保存回答，下一题','btn primary')}</div></div></section><aside class="stack"><section class="card"><h3>这次准备的重点</h3><ul class="clean-list"><li>${I('check')} 说清楚“团队做了什么”和“我做了什么”</li><li>${I('check')} 准备一次技术取舍的具体例子</li><li>${I('check')} 不确定的结果，不编造数字</li></ul>${act('practice-resume','查看投递材料','text-btn')}</section><section class="card"><h3>面试后，趁记忆还新鲜</h3><p class="label" style="margin:12px 0">记录被问到的问题、自己的回答，以及下次想改进的地方。</p>${act('review','写一份复盘','btn full')}</section>${state.reviews.filter(r=>r.mode===mode).map(r=>`<section class="card"><h3>${E(r.title)}</h3><p class="label">${E(r.body)}</p></section>`).join('')}</aside></div>`}
function admin(){return head('合作方管理','站外对接与核验，站内按约定开通。',pill('管理员视角 · 仅演示','orange'))+`<div class="stats">${[['合作方',state.partners.length],['已开通',state.partners.filter(p=>p.status==='已开通').length],['待处理',state.partners.filter(p=>p.status!=='已开通').length],['待核验回访',state.orders.filter(o=>o.reward==='待核验').length]].map(([t,n])=>`<div class="card stat"><span class="label">${t}</span><strong>${n}</strong></div>`).join('')}</div><div class="card table-wrap"><table><thead><tr><th>合作方</th><th>身份</th><th>核验 / 收款</th><th>有效期</th><th>权限状态</th><th>操作</th></tr></thead><tbody>${state.partners.map(p=>`<tr><td><strong>${p.name}</strong><br><span class="meta">${p.company}</span></td><td>${p.role}</td><td>${pill(p.verified?'已核验':'待核验',p.verified?'green':'orange')} ${pill(p.paid?'收款已确认':'待对接')}</td><td>${p.expires}</td><td>${pill(p.status,p.status==='已开通'?'green':'')}</td><td>${act('partner','管理权限','text-btn',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:20px">演示模式允许切换管理视角，用于评审流程；它不是真实登录或鉴权。正式产品中只有负责人可见这些操作。</div>`}
function adminOrders(){return head('服务与回访','分别核对服务履约、用户奖励与服务方应收。')+`<div class="stack">${state.orders.length?state.orders.map(o=>`<div class="card"><div class="row between"><div><h3>${E(o.provider)} · ${E(o.type)}</h3><p class="label">${o.id} · 实付示例 ¥${o.price} · ${o.status}</p></div>${pill(o.reward||'未申请回访',o.reward==='已核验 · 奖励待发放'?'green':'orange')}</div><p class="note" style="margin:18px 0">核验线索：${E(o.evidence||'用户尚未提交回访')}<br>反馈：${E(o.feedback||'暂无')}</p><div class="row between"><span class="label">手续费示例（15%）：¥${(o.price*.15).toFixed(2)} · 不自动扣款</span>${o.reward==='待核验'?act('verify-reward','记录核验结果','btn primary',`data-id="${o.id}"`):o.reward==='已核验 · 奖励待发放'?act('pay-reward','模拟奖励已发放','btn',`data-id="${o.id}"`):pill('等待下一步')}</div></div>`).join(''):'<div class="card empty">用户预约服务后，服务单和回访会显示在这里。</div>'}</div>`}
function provider(){return head('我的服务单','把每一次咨询，变成清楚、具体的帮助。',pill('服务方视角 · 演示','blue'))+ordersView()}
function currentResume(){return state.resumes.find(r=>r.id===selectedResume)||state.resumes[0]}
function checkpoint(r,label){const snap=clone(r);delete snap.versions;r.versions.push({id:uid(),label,time:new Date().toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}),snapshot:snap});persist()}
function addApplication(company,jobRole,resumeId,stage='准备中'){const r=state.resumes.find(r=>r.id===resumeId)||currentResume();const a={id:uid(),mode,company,role:jobRole,stage,date:'2026-09-16',resumeId:r.id,snapshot:clone(r),history:['9 月 16 日 · '+(stage==='准备中'?'创建申请，材料待准备':'用户确认已投递，保存材料快照')],note:''};state.applications.push(a);persist();return a}
const resumeOptions=()=>state.resumes.map(r=>`<option value="${r.id}">${E(r.name)}</option>`).join('');
function applicationDetail(id){const a=state.applications.find(a=>a.id===id);modal(`${E(a.company)} · ${E(a.role)}`,`<div class="row between">${pill(a.stage,'blue')}<span class="meta">${a.date}</span></div><label class="field" style="margin-top:20px"><span>更新申请阶段</span><select id="application-stage">${['准备中','已投递','面试','Offer','已结束'].map(s=>`<option ${a.stage===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="note">${I('file')} 材料快照：${E(a.snapshot.name)}<br>后续修改简历，不会覆盖这里的材料。</div><div class="row" style="margin:15px 0">${act('view-snapshot','查看当时材料','text-btn',`data-id="${a.id}"`)}</div><h3>进展时间线</h3><ul class="timeline">${a.history.map(h=>`<li>${E(h)}</li>`).join('')}</ul><label class="field"><span>备注与下一步</span><textarea id="application-note">${E(a.note)}</textarea></label>`,act('save-application','保存进展','btn primary',`data-id="${a.id}"`))}
function jobDetail(id){const c=companies.find(c=>c.id===id);modal('岗位详情',`<div class="row">${logo(c)}<div><h2>${c.name}</h2><span class="label">${c.city} · ${modes[mode].season}</span></div></div><h2 style="margin:22px 0 8px">${modes[mode].role}</h2><p>${c.desc}</p><div class="skill-row">${c.skills.split(' / ').map(s=>pill(s)).join('')}</div><h3 style="margin:22px 0 8px">岗位要求</h3><ul class="clean-list"><li>熟悉相关技术栈，能够清楚表达项目中的个人职责。</li><li>${mode==='intern'?'每周到岗 4 天，可连续实习 3 个月。':mode==='campus'?'面向 2027 届毕业生，以企业具体资格说明为准。':'有相关系统开发经历，能够解释技术取舍与业务结果。'}</li></ul><div class="note">演示岗位，不连接真实招聘系统。你可以体验准备材料、内推和投递记录流程。</div>`,act('referral','查看内推','btn',`data-id="${id}"`)+act('tailor','准备定向简历','btn primary',`data-id="${id}"`))}
function action(a,d){const r=currentResume();switch(a){
case 'close':close();break;
case 'switch':modal('切换求职模式',`<div class="stack">${Object.entries(modes).map(([k,v])=>`<button class="mode-option" data-mode="${k}"><span class="square-icon">${I(v.icon)}</span><div class="grow"><strong>${v.label}</strong><p class="label">${v.plan}</p></div>${mode===k?I('check'):I('arrow')}</button>`).join('')}</div><p class="note" style="margin-top:20px">材料保留，投递按计划分开。切换到社招不会自动开启猎头发现。</p>`);break;
case 'mobile-menu':modal('前往',`<nav class="nav">${navItems().map(([p,i,t])=>`<button data-page="${p}">${I(i)}${t}</button>`).join('')}</nav><div class="row" style="margin-top:20px">${act('switch','切换求职模式','btn')}${act('role','切换体验视角','btn')}</div>`);break;
case 'role':modal('切换体验视角',`<p class="note">这些是可体验的角色演示，不会创建真实账号或授予真实权限。</p><div class="stack" style="margin-top:20px">${[['user','个人求职者','体验简历、机会与服务'],['admin','平台负责人','人工开通合作方、核验回访'],['provider','人工服务方','查看服务单与推进交付']].map(([id,t,p])=>`<button class="mode-option" data-act="set-role" data-id="${id}"><span class="square-icon">${I(id==='admin'?'settings':'people')}</span><div class="grow"><strong>${t}</strong><p class="label">${p}</p></div>${I('arrow')}</button>`).join('')}</div>`);break;
case 'set-role':role=d.id;close();go(role==='admin'?'admin':role==='provider'?'provider':'today');break;
case 'notifications':modal('通知中心',`<div class="task"><span class="square-icon">${I('calendar')}</span><div><h3>星野网络笔试安排待确认</h3><p class="label">9 月 18 日 19:00 — 21:00</p>${act('confirm-notice','查看并确认','text-btn')}</div></div><div class="task"><span class="square-icon">${I('file')}</span><div><h3>原型说明</h3><p class="label">所有交易、核验与 AI 反馈均为演示，不会扣款或发送材料。</p></div></div>`);break;
case 'prepare':close();go('practice');break;
case 'edit-first':selectedResume=state.resumes[0].id;editorTab='edit';go('resumes');break;
case 'confirm-notice':modal('确认笔试安排',`<p class="label">来自演示通知 · 不会读取你的邮箱</p><h3 style="margin:18px 0">星野网络 · 在线笔试</h3><p>2026 年 9 月 18 日，19:00 — 21:00（北京时间）</p><div class="note" style="margin-top:18px">请提前准备网络与电脑。该通知是固定时间考试，不是截止前任意参加。</div>`,act('confirm-notice-done',state.tasksDone.includes(mode+'t3')?'已确认':'确认并加入日程','btn primary'));break;
case 'confirm-notice-done':if(!state.tasksDone.includes(mode+'t3'))state.tasksDone.push(mode+'t3');persist();close();render();toast('已确认笔试安排');break;
case 'new-resume':formModal('新建一份简历',field('简历名称','name','我的新简历')+`<label class="field"><span>创建方式</span><select name="method"><option value="blank">从空白开始</option><option value="copy">复制当前简历</option></select></label>`,'创建简历',f=>{const x=f.get('method')==='copy'?clone(r):newResume(f.get('name'));x.id=uid();x.name=f.get('name').trim();if(!x.name)return;x.versions=[];if(f.get('method')==='blank'){x.experiences=[];x.person='你的姓名';x.headline='填写求职方向';x.education='填写教育经历';x.contact='填写联系方式'}checkpoint(x,'创建简历');state.resumes.push(x);selectedResume=x.id;editorTab='edit';persist();close();render();toast('已创建独立简历')});break;
case 'select-resume':selectedResume=d.id;editorTab='edit';render();break;
case 'editor-tab':editorTab=d.id;render();break;
case 'duplicate':{const x=clone(r);x.id=uid();x.name=r.name+' · 副本';x.versions=[];checkpoint(x,'从 '+r.name+' 复制');state.resumes.push(x);selectedResume=x.id;persist();render();toast('已复制，后续修改互不影响');break}
case 'rename':formModal('重命名简历',field('名称','name',r.name),'保存',f=>{r.name=f.get('name').trim()||r.name;persist();close();render()});break;
case 'save-version':formModal('保存一个版本',field('版本名称','name','内容调整 · '+(r.versions.length+1))+'<p class="note">保存当前内容和经历显隐，稍后可比较或恢复。</p>','保存版本',f=>{checkpoint(r,f.get('name').trim()||'新版本');close();render();toast('版本快照已保存')});break;
case 'compare-version':{const v=r.versions.find(v=>v.id===d.id);modal('版本比较',`<div class="compare-grid"><div><h3>${E(v.label)}</h3>${resumePaper(v.snapshot)}</div><div><h3>当前编辑内容</h3>${resumePaper(r)}</div></div>`,act('restore-version','恢复此版本','btn primary',`data-id="${d.id}"`));document.getElementById('dialog').classList.add('wide');break}
case 'restore-version':{const v=r.versions.find(v=>v.id===d.id);const originalId=r.id,vs=r.versions;Object.assign(r,clone(v.snapshot),{id:originalId,versions:vs});checkpoint(r,'恢复自：'+v.label);close();render();toast('已恢复，并新增恢复版本');break}
case 'add-experience':formModal('添加经历',field('经历名称','title')+field('时间范围','date','2026.01 — 2026.06')+`<label class="field"><span>经历描述</span><textarea name="body" required placeholder="描述你真实参与的事情、职责和结果"></textarea></label>`,'加入当前简历',f=>{r.experiences.push({id:uid(),title:f.get('title'),date:f.get('date'),body:f.get('body'),visible:true});persist();close();render()});break;
case 'ai-edit':{const x=r.experiences.find(e=>e.id===d.id);const proposed=x.body.replace('参与内部任务调度平台开发，','在内部任务调度平台中，').replace('与三位同学共同完成校园交易项目，','在四人协作的校园交易项目中，');modal('表达优化 · 示例预览',`<p class="note">原型展示预设改写，不调用真实模型。隐藏的经历不会被加入。</p><h3 style="margin:18px 0 8px">原句</h3><p>${E(x.body)}</p><h3 style="margin:18px 0 8px">建议</h3><p class="diff-added">${E(proposed)}</p><p class="meta">调整表达顺序，保留原有事实和技术信息。</p>`,act('apply-ai','接受到当前简历','btn primary',`data-id="${x.id}"`));break}
case 'apply-ai':{const x=r.experiences.find(e=>e.id===d.id);x.body=x.body.replace('参与内部任务调度平台开发，','在内部任务调度平台中，').replace('与三位同学共同完成校园交易项目，','在四人协作的校园交易项目中，');checkpoint(r,'接受示例表达优化');close();render();toast('已保存改写版本');break}
case 'export':modal('导出简历',`<p>选择导出方式。PDF 使用浏览器打印，结构化文件保留当前内容。</p>${r.reference?'<p class="note" style="margin-top:12px">此简历含市场参考内容，请先替换为你的真实经历。</p>':''}`,act('download-json','下载 JSON','btn')+act('print-resume','打印 / 保存 PDF','btn primary'));break;
case 'download-json':{const file=JSON.stringify(r,null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([file],{type:'application/json'}));a.download=r.name+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已导出当前简历');break}
case 'print-resume':{close();let div=document.getElementById('print-surface');if(!div){div=document.createElement('div');div.id='print-surface';document.body.appendChild(div)}div.innerHTML=resumePaper(r);window.print();break}
case 'publish-resume':formModal('创建市场发布副本',field('作品名称','title',r.name+' · 方法与样例')+field('演示价格（元）','price','29','number')+`<div class="note">将从当前版本建立独立发布草稿。演示中自动隐藏联系方式，不会真的上架。</div><label class="check" style="margin-top:16px"><input type="checkbox" required>我已检查发布内容与第三方信息</label>`,'预览发布草稿',f=>{const copy=clone(r);copy.contact='联系方式已隐藏';copy.person='匿名作者';modal('发布草稿 · 未上架',`<h3>${E(f.get('title'))} · ¥${E(f.get('price'))}</h3>${resumePaper(copy)}<p class="note">正式发布前还需完成授权与审核。本原型不会产生真实商品。</p>`)});break;
case 'add-job':case 'add-application':formModal(a==='add-job'?'记录一个新机会':'记录投递',field('公司','company')+field('岗位','job',modes[mode].role)+`<label class="field"><span>关联简历</span><select name="resume">${resumeOptions()}</select></label><label class="field"><span>当前阶段</span><select name="stage"><option>准备中</option><option>已投递</option></select></label><p class="note">只有你确认已经提交，才选择“已投递”。</p>`,'保存记录',f=>{addApplication(f.get('company'),f.get('job'),f.get('resume'),f.get('stage'));close();go('applications');toast('申请已记录')});break;
case 'favorite':state.favorites=state.favorites.includes(d.id)?state.favorites.filter(x=>x!==d.id):[...state.favorites,d.id];persist();render();break;
case 'filter':filter=d.id;render();break;
case 'job':jobDetail(d.id);break;
case 'tailor':{const c=companies.find(c=>c.id===d.id);const x=clone(r);x.id=uid();x.name=c.name+' · '+modes[mode].label+'定向版';x.kind='岗位定向';x.versions=[];checkpoint(x,'从 '+r.name+' 派生');state.resumes.push(x);selectedResume=x.id;editorTab='edit';persist();close();go('resumes');toast('已创建定向副本，请根据岗位继续编辑；尚未投递');break}
case 'referral':{const c=companies.find(c=>c.id===d.id);modal(c.name+' · 内推入口',`<div class="row">${logo(c)}<div><h3>苏同学 · 内推合作方</h3><span class="meta">适用：${modes[mode].season} · 员工身份演示已核验</span></div></div><div class="referral-code"><span class="label">演示推荐码</span><strong>${c.ref}</strong></div><p class="note">复制推荐码不等于提交成功。如已通过其他渠道申请，应先确认是否支持重复推荐。</p><label class="field" style="margin-top:16px"><span>选择提供给内推人的简历</span><select id="referral-resume">${resumeOptions()}</select></label>`,act('copy-code','复制演示码','btn',`data-code="${c.ref}"`)+act('request-referral','模拟请求内推','btn primary',`data-id="${d.id}"`));break}
case 'copy-code':navigator.clipboard?.writeText(d.code).then(()=>toast('演示码已复制')).catch(()=>toast('可手动选择上方推荐码复制'));break;
case 'request-referral':{const c=companies.find(c=>c.id===d.id),a=addApplication(c.name,modes[mode].role,document.getElementById('referral-resume').value);a.history.push('9 月 16 日 · 模拟内推请求，等待对方确认');persist();close();go('applications');toast('已记录内推意向；没有向外发送，尚未投递');break}
case 'app-view':appView=d.id;render();break;
case 'application':applicationDetail(d.id);break;
case 'save-application':{const a=state.applications.find(a=>a.id===d.id),stage=document.getElementById('application-stage').value;a.note=document.getElementById('application-note').value;if(a.stage!==stage){a.history.push('9 月 16 日 · 用户更新阶段：'+stage);if(a.stage==='准备中'&&stage==='已投递')a.snapshot=clone(state.resumes.find(r=>r.id===a.resumeId)||a.snapshot);a.stage=stage}persist();close();render();toast('进展已保存');break}
case 'view-snapshot':{const a=state.applications.find(a=>a.id===d.id);modal('当时的材料 · 固定快照',resumePaper(a.snapshot));break}
case 'product':{const p=products.find(p=>p.id===d.id);modal(p.title,`<div class="row between"><span class="label">${p.author} · ${p.tags}</span><strong class="price">¥${p.price}</strong></div><p style="margin:18px 0">${p.desc}</p>${miniResume({person:p.author,headline:p.title,experiences:experienceSeed})}<div class="note">个人求职使用，可编辑和重复导出；不包含转售权，不提供作者联系方式。付款和导入在此仅作演示。</div>`,act('purchase',state.purchases.includes(p.id)?'选择导入方式':'模拟购买并选择导入','btn primary',`data-id="${p.id}"`));break}
case 'purchase':{const p=products.find(p=>p.id===d.id);if(!state.purchases.includes(p.id))state.purchases.push(p.id);persist();modal('已获得演示授权 · 选择导入方式',`<div class="stack"><button class="mode-option" data-act="import-product" data-id="${p.id}" data-method="layout"><span class="square-icon">${I('file')}</span><div><h3>只用布局，填写我的经历</h3><p class="label">获得空白结构，不导入作者经历。</p></div></button><button class="mode-option" data-act="import-product" data-id="${p.id}" data-method="example"><span class="square-icon">${I('grid')}</span><div><h3>导入可编辑样例</h3><p class="label">示例保留“参考内容”标记，不算作你的经历。</p></div></button></div><p class="note" style="margin-top:18px">没有发生真实扣款。导入会创建新简历，不覆盖已有内容。</p>`);break}
case 'import-product':{const p=products.find(p=>p.id===d.id),x=newResume(p.title+' · 我的副本','市场导入');x.template='market-'+p.id;x.reference=d.method==='example';if(!x.reference)x.experiences=[];else{x.person='待替换姓名';x.contact='请填写你的联系方式'}x.versions=[];checkpoint(x,'市场作品导入');state.resumes.push(x);selectedResume=x.id;editorTab='edit';persist();close();go('resumes');toast('已导入独立简历副本');break}
case 'my-purchases':modal('我的购买 · 演示',state.purchases.length?state.purchases.map(id=>{const p=products.find(p=>p.id===id);return `<div class="task"><div class="grow"><h3>${p.title}</h3><span class="meta">个人使用授权 · ¥${p.price}（模拟）</span></div>${act('purchase','再次导入','btn',`data-id="${id}"`)}</div>`}).join(''):'<div class="empty">还没有购买作品，可以先预览喜欢的简历。</div>');break;
case 'service-view':serviceView=d.id;render();break;
case 'book':{const s=servicesData.find(s=>s.id===d.id);formModal('预约'+s.type,`<div class="row"><span class="expert-avatar" style="background:${s.color}">${s.initial}</span><div><h3>${s.name} · ¥${s.price}</h3><p class="label">${s.detail}</p></div></div><label class="field" style="margin-top:20px"><span>预约时段（演示）</span><select name="slot"><option>9 月 18 日 20:00</option><option>9 月 19 日 10:00</option><option>9 月 20 日 15:00</option></select></label><label class="field"><span>本次提供的简历</span><select name="resume">${resumeOptions()}</select></label><label class="field"><span>最希望解决的问题</span><textarea name="need" placeholder="例如：项目经历不知道怎么取舍" required></textarea></label><label class="check"><input name="consent" type="checkbox" required>仅授权本服务单使用所选材料</label><p class="note" style="margin-top:16px">原型不会收费或发送资料。正式服务需先确认报价、交付、改期和退款规则。</p>`,'创建演示服务单',f=>{const res=state.resumes.find(r=>r.id===f.get('resume'));state.orders.push({id:uid(),type:s.type,provider:s.name,price:s.price,detail:s.detail,slot:f.get('slot'),need:f.get('need'),resumeName:res.name,status:'待确认',mode,eventId:state.bookingContext?.eventId});state.bookingContext=null;persist();close();serviceView='orders';render();toast('已创建服务单，等待服务方确认（演示）')});break}
case 'order-step':{const o=state.orders.find(o=>o.id===d.id);o.status=o.status==='待确认'?'待服务':'已完成';persist();render();toast('演示服务状态已更新');break}
case 'order-support':formModal('改期 / 售后',`<label class="field"><span>需要什么帮助</span><select name="type"><option>申请改期</option><option>反馈交付问题</option><option>申请退款</option></select></label><label class="field"><span>说明</span><textarea name="reason" required></textarea></label>`,'记录请求',f=>{const o=state.orders.find(o=>o.id===d.id);o.support=f.get('type')+'：'+f.get('reason');persist();close();toast('请求已记录（演示），可联系平台负责人协调')});break;
case 'reward-rules':modal('¥10 真实回访奖励 · 演示规则',`<ul class="clean-list"><li>适用于平台已建单且完成交付的演示服务。</li><li>每个完整订单最多申请一次；套餐不拆分领奖。</li><li>提交必要的付款/交付线索，可遮盖无关信息。</li><li>真实负面反馈同样可申请，不要求好评。</li><li>核验服务与退款情况后，奖励和商家手续费分别处理。</li></ul><div class="note">本原型不接受真实凭证，不发放现金。正式活动的适用金额、时限和预算仍待确定。</div>`);break;
case 'claim-reward':formModal('提交回访 · 申请 ¥10',`<p class="note">请使用虚构内容体验，不上传真实付款资料。回访奖励与评价好坏无关。</p><label class="field" style="margin-top:16px"><span>付款与交付线索（演示）</span><textarea name="evidence" placeholder="例如：演示付款编号 TEST001；已收到修改版简历" required></textarea></label><label class="field"><span>真实体验反馈</span><textarea name="feedback" placeholder="哪些有帮助，哪些不满意？" required></textarea></label><label class="check"><input type="checkbox" required>确认该演示服务已经完成</label>`,'提交核验',f=>{const o=state.orders.find(o=>o.id===d.id);o.reward='待核验';o.evidence=f.get('evidence');o.feedback=f.get('feedback');persist();close();render();toast('回访已进入待核验，可切换负责人视角继续体验')});break;
case 'verify-reward':formModal('核验回访',`<label class="check"><input type="checkbox" required>平台来源、付款与交付线索已核对</label><label class="check" style="margin:14px 0"><input type="checkbox" required>已核对退款、重复申请及服务方意见</label><label class="field"><span>处理结果</span><select name="result"><option>核验通过</option><option>需要补充材料</option></select></label><p class="note">只记录演示核验，不自动扣服务方费用。</p>`,'保存核验结果',f=>{const o=state.orders.find(o=>o.id===d.id);o.reward=f.get('result')==='核验通过'?'已核验 · 奖励待发放':'待补充材料';persist();close();render()});break;
case 'pay-reward':{const o=state.orders.find(o=>o.id===d.id);o.reward='演示奖励已发放 ¥10';persist();render();toast('仅更新演示记录，没有发生转账');break}
case 'discovery':formModal('社招人才展示',`<label class="field"><span>允许展示的简历</span><select name="resume">${resumeOptions()}</select></label><label class="check"><input type="checkbox" name="allow" ${state.discovery?'checked':''}>允许已核验猎头发现我的社招资料</label><p class="note" style="margin-top:18px">只开放选择的版本，不包含其他简历、投递和私人复盘。推荐给具体企业仍需另行授权。</p>`,'保存展示范围',f=>{if(mode!=='social')return;state.discovery=f.has('allow');state.discoveryResume=f.get('resume');persist();close();render();toast(state.discovery?'已开启社招展示（演示）':'已关闭社招展示')});break;
case 'hunter-invite':if(state.invites.includes(d.name)){toast('已记录意向，没有发送外部消息');break}formModal('向 '+E(d.name)+' 表达沟通意向',`<label class="field"><span>提供的简历</span><select name="resume">${resumeOptions()}</select></label><p class="note">该操作只记录对当前岗位的沟通意向。向企业推荐前仍需确认具体公司和材料。</p><label class="check" style="margin-top:16px"><input type="checkbox" required>同意本次沟通使用选择的演示材料</label>`,'模拟提交意向',()=>{state.invites.push(d.name);persist();close();render();toast('沟通意向已记录，没有向外发送')});break;
case 'practice-human':filter='模拟面试';serviceView='browse';page='services';render();break;
case 'practice-next':{const answer=document.getElementById('practice-answer').value.trim();if(!answer){toast('先写一点你的思路，再继续');document.getElementById('practice-answer').focus();break}practiceAnswers[practiceStep]=answer;if(practiceStep<2){practiceStep++;render()}else{if(!state.tasksDone.includes(mode+'t1'))state.tasksDone.push(mode+'t1');persist();modal('这次练习已完成',`<p>你完成了三道围绕项目的追问。接下来可以对照下面的维度复查。</p><ul class="clean-list"><li>是否把自己的职责和团队职责区分清楚？</li><li>是否解释了选择方案的原因和取舍？</li><li>是否指出了仍待确认的结果？</li></ul><p class="note">这是固定的示例复查清单，不是模型对你回答的真实评分。</p>`,act('review','记录本次复盘','btn primary'))}break}
case 'practice-resume':{const a=state.applications.find(a=>a.mode===mode&&a.company==='青禾科技');modal('面试准备 · 提交材料快照',resumePaper(a?.snapshot||r));break}
case 'review':formModal('记录面试复盘',field('标题','title','青禾科技 · 技术一面复盘')+`<label class="field"><span>问题、回答与下一步</span><textarea name="body" required placeholder="记录被问到的问题，哪里回答得不够清楚，下次想怎么改进"></textarea></label>`,'保存复盘',f=>{state.reviews.push({title:f.get('title'),body:f.get('body'),mode});persist();close();render();toast('复盘已保存，不会自动改写简历')});break;
case 'partner':{const p=state.partners.find(p=>p.id===d.id);formModal(p.name+' · 合作权限',`<p class="note">站外沟通、核验和收费由负责人完成。这里仅记录开通结果，演示不代表真实鉴权。</p><label class="check" style="margin-top:18px"><input type="checkbox" name="verified" ${p.verified?'checked':''}>身份与机构关联已核验</label><label class="check" style="margin:14px 0"><input type="checkbox" name="paid" ${p.paid?'checked':''}>约定的收款 / 合作条件已确认</label>${field('权限到期日','expires',p.expires,'date')}<label class="field"><span>权限状态</span><select name="status">${['待核验','待开通','已开通','已暂停'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`,'保存权限',f=>{if(f.get('status')==='已开通'&&(!f.has('verified')||!f.has('paid'))){document.getElementById('form-error').textContent='请先完成身份核验与约定合作条件，付款不能替代核验。';return}p.verified=f.has('verified');p.paid=f.has('paid');p.status=f.get('status');p.expires=f.get('expires');persist();close();render();toast('演示权限记录已更新')});break}
case 'reset':modal('重置演示数据',`<p>将清除本浏览器中对原型的修改、演示订单和投递记录，恢复初始样例。</p>`,act('close','保留修改','btn')+act('reset-confirm','重置演示','btn danger'));break;
case 'reset-confirm':state=clone(seed);mode=null;role='user';page='today';selectedResume=state.resumes[0].id;persist();close();render();break;
}}
document.addEventListener('click',e=>{const m=e.target.closest('[data-mode]');if(m){close();chooseMode(m.dataset.mode);return}const n=e.target.closest('[data-page]');if(n){close();go(n.dataset.page);return}const a=e.target.closest('[data-act]');if(a)action(a.dataset.act,a.dataset)});
document.addEventListener('input',e=>{if(e.target.id==='search-input'){query=e.target.value;const pos=e.target.selectionStart;render();const el=document.getElementById('search-input');el.focus();el.setSelectionRange(pos,pos);return}const r=currentResume();if(e.target.dataset.expField){r.experiences.find(x=>x.id===e.target.dataset.expId)[e.target.dataset.expField]=e.target.value;persist();const preview=document.getElementById('resume-preview');if(preview)preview.innerHTML=resumePaper(r)}if(e.target.dataset.edit){r[e.target.dataset.edit]=e.target.value;persist();document.getElementById('resume-preview').innerHTML=resumePaper(r)}if(e.target.dataset.expText){r.experiences.find(x=>x.id===e.target.dataset.expText).body=e.target.value;persist();document.getElementById('resume-preview').innerHTML=resumePaper(r)}});
document.addEventListener('change',e=>{if(e.target.dataset.expVisible){const r=currentResume();r.experiences.find(x=>x.id===e.target.dataset.expVisible).visible=e.target.checked;persist();render();toast(e.target.checked?'经历已显示':'已隐藏，仅影响当前简历')}});
document.getElementById('dialog').addEventListener('close',()=>document.getElementById('dialog').classList.remove('wide'));
document.getElementById('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
if(document.modelContext?.registerTool){const life=new AbortController();const tools=[{name:'read_career_prototype',description:'Read demo workspace mode, page and local resume names. No external data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode,page,resumes:state.resumes.map(r=>({id:r.id,name:r.name,versions:r.versions.length}))})},{name:'switch_job_search_mode',description:'Switch the visible prototype to internship, campus or social job search. Updates local demo preference only.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['intern','campus','social']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!modes[input.mode])throw Error('Invalid mode');chooseMode(input.mode);return {mode,page}}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
